BEGIN;
CREATE TABLE IF NOT EXISTS platform.execution_batches(tenant_id uuid NOT NULL,batch_id uuid NOT NULL,endpoint_id uuid NOT NULL,agent_id uuid NOT NULL,installation_id text NOT NULL,first_sequence bigint NOT NULL,last_sequence bigint NOT NULL,event_count integer NOT NULL,content_sha256 text NOT NULL,received_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(tenant_id,batch_id));
CREATE TABLE IF NOT EXISTS platform.execution_events(tenant_id uuid NOT NULL,event_id uuid NOT NULL,batch_id uuid NOT NULL,endpoint_id uuid NOT NULL,agent_id uuid NOT NULL,event_type text NOT NULL,entity_id text NOT NULL,source_process_entity_id text,target_process_entity_id text,source_pid integer,target_pid integer,operation text NOT NULL,handle_type text,access_mask bigint,memory_protection bigint,executable_memory boolean,thread_id integer,start_address numeric(20,0),section_entity_id text,sequence bigint NOT NULL,observed_at timestamptz NOT NULL,data_quality_flags text[] NOT NULL DEFAULT '{}',event_data jsonb NOT NULL,PRIMARY KEY(tenant_id,event_id),UNIQUE(tenant_id,agent_id,sequence));
CREATE INDEX IF NOT EXISTS ix_execution_events_search ON platform.execution_events(tenant_id,observed_at DESC,event_id DESC);
CREATE INDEX IF NOT EXISTS ix_execution_events_source ON platform.execution_events(tenant_id,source_process_entity_id,observed_at DESC);
CREATE INDEX IF NOT EXISTS ix_execution_events_target ON platform.execution_events(tenant_id,target_process_entity_id,observed_at DESC);
CREATE INDEX IF NOT EXISTS ix_execution_events_thread ON platform.execution_events(tenant_id,endpoint_id,thread_id,observed_at DESC);
CREATE TABLE IF NOT EXISTS platform.execution_process_handle_relationships(tenant_id uuid NOT NULL,event_id uuid NOT NULL,endpoint_id uuid NOT NULL,source_process_entity_id text,target_process_entity_id text,handle_type text NOT NULL,desired_access bigint NOT NULL,granted_access bigint,observed_at timestamptz NOT NULL,evidence jsonb NOT NULL,PRIMARY KEY(tenant_id,event_id));
CREATE TABLE IF NOT EXISTS platform.execution_thread_entities(tenant_id uuid NOT NULL,endpoint_id uuid NOT NULL,thread_entity_id text NOT NULL,process_entity_id text NOT NULL,thread_id integer NOT NULL,first_observed timestamptz NOT NULL,last_observed timestamptz NOT NULL,start_address numeric(20,0),latest_event jsonb NOT NULL,PRIMARY KEY(tenant_id,endpoint_id,thread_entity_id));
CREATE TABLE IF NOT EXISTS platform.execution_memory_regions(tenant_id uuid NOT NULL,endpoint_id uuid NOT NULL,region_entity_id text NOT NULL,process_entity_id text NOT NULL,base_address numeric(20,0) NOT NULL,size numeric(20,0) NOT NULL,first_observed timestamptz NOT NULL,last_observed timestamptz NOT NULL,latest_state jsonb NOT NULL,PRIMARY KEY(tenant_id,endpoint_id,region_entity_id));
CREATE TABLE IF NOT EXISTS platform.execution_memory_protection_history(tenant_id uuid NOT NULL,event_id uuid NOT NULL,endpoint_id uuid NOT NULL,region_entity_id text NOT NULL,protection_before bigint,protection_after bigint,observed_at timestamptz NOT NULL,evidence jsonb NOT NULL,PRIMARY KEY(tenant_id,event_id));
CREATE TABLE IF NOT EXISTS platform.execution_section_entities(tenant_id uuid NOT NULL,endpoint_id uuid NOT NULL,section_entity_id text NOT NULL,first_observed timestamptz NOT NULL,last_observed timestamptz NOT NULL,latest_state jsonb NOT NULL,PRIMARY KEY(tenant_id,endpoint_id,section_entity_id));
CREATE TABLE IF NOT EXISTS platform.execution_section_mappings(tenant_id uuid NOT NULL,event_id uuid NOT NULL,endpoint_id uuid NOT NULL,section_entity_id text NOT NULL,process_entity_id text,mapped_base numeric(20,0),observed_at timestamptz NOT NULL,evidence jsonb NOT NULL,PRIMARY KEY(tenant_id,event_id));
CREATE TABLE IF NOT EXISTS platform.execution_telemetry_health(tenant_id uuid NOT NULL,endpoint_id uuid NOT NULL,health_data jsonb NOT NULL,updated_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(tenant_id,endpoint_id));
CREATE TABLE IF NOT EXISTS platform.execution_policy_versions(id uuid PRIMARY KEY,tenant_id uuid NOT NULL,name text NOT NULL,version integer NOT NULL,policy jsonb NOT NULL,sha256 text NOT NULL,status text NOT NULL,created_at timestamptz NOT NULL,created_by text NOT NULL,UNIQUE(tenant_id,name,version));
CREATE TABLE IF NOT EXISTS platform.execution_policy_assignments(tenant_id uuid NOT NULL,endpoint_id uuid NULL,policy_id uuid NOT NULL REFERENCES platform.execution_policy_versions(id),assigned_at timestamptz NOT NULL,assigned_by text NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS ux_execution_policy_assignment ON platform.execution_policy_assignments(tenant_id,COALESCE(endpoint_id,'00000000-0000-0000-0000-000000000000'::uuid));
CREATE TABLE IF NOT EXISTS platform.execution_policy_acknowledgements(tenant_id uuid NOT NULL,endpoint_id uuid NOT NULL,policy_id uuid NOT NULL,version integer NOT NULL,applied boolean NOT NULL,validation_error text,acknowledged_at timestamptz NOT NULL,PRIMARY KEY(tenant_id,endpoint_id));
CREATE TABLE IF NOT EXISTS platform.execution_export_jobs(id uuid PRIMARY KEY,tenant_id uuid NOT NULL,created_by text NOT NULL,state text NOT NULL,format text NOT NULL,query jsonb NOT NULL,fields text[] NOT NULL,maximum_records integer NOT NULL,output_object_id uuid NOT NULL,manifest_object_id uuid NOT NULL,metadata_object_id uuid NOT NULL,created_at timestamptz NOT NULL,updated_at timestamptz NOT NULL,expires_at timestamptz NOT NULL,started_at timestamptz,completed_at timestamptz,record_count integer,output_size bigint,output_sha256 text,error_code text,error_summary text);
COMMIT;
